from collections import deque
n, m = map(int, input().split())
g = [list(input().strip()) for _ in range(n)]
count = 0
for i in range(n):
    for j in range(m):
        if g[i][j] == "#":
            count += 1
            g[i][j] = "."
            q = deque([(i, j)])
            while q:
                r, c = q.popleft()
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < n and 0 <= nc < m and g[nr][nc] == "#":
                        g[nr][nc] = "."
                        q.append((nr, nc))
