n = int(input())
d = [list(map(int, input().split())) for _ in range(n)]
m = n - 1
FULL = 1 << m
INF = float("inf")
dp = [[INF] * m for _ in range(FULL)]
for j in range(m):
    dp[1 << j][j] = d[0][j + 1]
for mask in range(1, FULL):
    row = dp[mask]
    for j in range(m):
        cur = row[j]
        if cur == INF or not mask >> j & 1:
            continue
        dj = d[j + 1]
        for k in range(m):
            if not mask >> k & 1:
                nm = mask | 1 << k
                v = cur + dj[k + 1]
                if v < dp[nm][k]:
                    dp[nm][k] = v
print(min(dp[FULL - 1][j] + d[j + 1][0] for j in range(m)))

def count(N):
    s = str(N)
    L = len(s)
    total = sum(9 ** length for length in range(1, L))
    prev = -1
    for i, ch in enumerate(s):
        d = int(ch)
        for x in range(1 if i == 0 else 0, d):
            if x != prev:
                total += 9 ** (L - i - 1)
        if d == prev:
            return total
        prev = d
    return total + 1
